<?php
require_once __DIR__.'/../config/database.php';require_login();$uid=(int)$_SESSION['user_id'];$total=(int)$conn->query('SELECT COUNT(*) FROM lessons')->fetchColumn();$q=$conn->prepare('SELECT COUNT(*) FROM lesson_progress WHERE user_id=?');$q->execute([$uid]);$done=(int)$q->fetchColumn();$q=$conn->prepare('SELECT COUNT(*) FROM activity_progress WHERE user_id=?');$q->execute([$uid]);$labs=(int)$q->fetchColumn();$q=$conn->prepare('SELECT score,total,attempted_at,q.title FROM quiz_attempts a JOIN quizzes q ON q.id=a.quiz_id WHERE user_id=? ORDER BY attempted_at DESC LIMIT 5');$q->execute([$uid]);$attempts=$q->fetchAll();$lessons=$conn->query('SELECT id,title,category,minutes FROM lessons ORDER BY sort_order LIMIT 3')->fetchAll();$pct=$total?round($done*100/$total):0;$pageTitle='My learning';require __DIR__.'/../partials/header.php'; ?>
<section class="dashboard-hero"><div><span class="eyebrow">YOUR LEARNING SPACE</span><h1>Good to see you, <?= e(explode(' ',$_SESSION['fullname'])[0]) ?>.</h1><p>Keep your momentum going. Every small step builds a stronger foundation.</p></div><div class="progress-ring" style="--progress:<?= $pct ?>"><strong><?= $pct ?>%</strong><span>LESSONS<br>COMPLETE</span></div></section><section class="content-wrap dashboard-content"><div class="metric-grid"><div class="metric-card"><span>Lessons finished</span><strong><?= $done ?><small> / <?= $total ?></small></strong><div class="progress-bar"><i style="width:<?= $pct ?>%"></i></div></div><div class="metric-card"><span>Practice labs</span><strong><?= $labs ?></strong><small>completed</small></div><div class="metric-card"><span>Quiz attempts</span><strong><?= count($attempts) ?></strong><small>recent results</small></div></div><div class="dashboard-columns"><section class="panel"><div class="section-heading"><div><span class="eyebrow">PICK UP HERE</span><h2>Continue learning</h2></div><a class="text-link" href="<?= e(app_url('lessons.php')) ?>">All lessons ↗</a></div><?php foreach($lessons as $l): ?><a class="continue-row" href="<?= e(app_url('lesson.php?id='.(int)$l['id'])) ?>"><span class="lesson-number">↗</span><span><b><?= e($l['title']) ?></b><small><?= e($l['category']) ?> · <?= (int)$l['minutes'] ?> min</small></span></a><?php endforeach; ?><a class="button button-quiet" href="<?= e(app_url('activities.php')) ?>">Explore practice labs →</a></section><section class="panel"><div class="section-heading"><div><span class="eyebrow">RECENT RESULTS</span><h2>Quiz activity</h2></div><a class="text-link" href="<?= e(app_url('quizzes.php')) ?>">All quizzes ↗</a></div><?php if(!$attempts): ?><p class="muted">Your quiz results will appear here after your first attempt.</p><?php else: foreach($attempts as $a): ?><div class="result-row"><span><b><?= e($a['title']) ?></b><small><?= e(date('M j, Y',strtotime($a['attempted_at']))) ?></small></span><strong><?= (int)$a['score'] ?>/<?= (int)$a['total'] ?></strong></div><?php endforeach; endif; ?></section></div></section><?php require __DIR__.'/../partials/footer.php'; ?>
